-- Part C: Prisma-unrepresentable objects (functions, triggers, CHECKs, expression indexes)
-- Functions (plpgsql)
CREATE OR REPLACE FUNCTION public.append_token_usage_billing_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE
        billing_event_type TEXT;
      BEGIN
        IF TG_OP = 'INSERT' THEN
          billing_event_type := CASE
            WHEN NEW.task_queue_id IS NULL AND NEW.billing_status IN ('pending_reconciliation', 'unallocated')
              THEN 'usage_discovered'
            ELSE 'usage_recorded'
          END;
        ELSIF OLD.task_queue_id IS NULL AND NEW.task_queue_id IS NOT NULL THEN
          billing_event_type := 'usage_attributed';
        ELSE
          billing_event_type := 'billing_state_changed';
        END IF;

        INSERT INTO token_usage_billing_event (
          id, workspace_id, token_usage_id, event_type, snapshot_json, created_at
        ) VALUES (
          'billing-event-' || md5(NEW.id || clock_timestamp()::text || random()::text),
          NEW.workspace_id,
          NEW.id,
          billing_event_type,
          to_jsonb(NEW),
          clock_timestamp()
        );
        RETURN NEW;
      END;
      $function$;
CREATE OR REPLACE FUNCTION public.assign_workflow_run_history_sequence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        IF NEW.history_sequence IS NULL THEN
          UPDATE workspace
             SET workflow_run_sequence = workflow_run_sequence + 1
           WHERE id = NEW.workspace_id
           RETURNING workflow_run_sequence INTO NEW.history_sequence;
        END IF;
        RETURN NEW;
      END;
      $function$;
CREATE OR REPLACE FUNCTION public.guard_schema_version_monotonic()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      DECLARE old_int bigint; new_int bigint;
      BEGIN
        IF NEW.key IS DISTINCT FROM 'schema_version' THEN
          RETURN NEW;
        END IF;
        BEGIN
          new_int := NEW.value::bigint;
        EXCEPTION WHEN invalid_text_representation THEN
          RETURN NEW;
        END;
        IF TG_OP = 'UPDATE' AND OLD IS NOT NULL THEN
          BEGIN
            old_int := OLD.value::bigint;
          EXCEPTION WHEN invalid_text_representation THEN
            RETURN NEW;
          END;
          IF new_int < old_int THEN
            RAISE EXCEPTION 'schema_version cannot be downgraded from % to %',
              OLD.value, NEW.value USING ERRCODE = 'check_violation';
          END IF;
        END IF;
        RETURN NEW;
      END;
      $function$;
CREATE OR REPLACE FUNCTION public.sync_employee_display_name()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        IF NEW.name IS DISTINCT FROM OLD.name THEN
          UPDATE agent_skill SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE agent_skill_requirement_config SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE agent_knowledge_page SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE employee_persistent_workspace SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE employee_workspace_revision SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE employee_artifact SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE employee_runtime_binding SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE employee_recovery_operation SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE task_commit_journal SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
          UPDATE runtime_workspace_mount_operation SET employee_name = NEW.name
           WHERE workspace_id = NEW.workspace_id AND employee_id = NEW.id;
        END IF;
        RETURN NEW;
      END;
      $function$;
CREATE OR REPLACE FUNCTION public.validate_delegated_token_usage_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
      BEGIN
        IF NEW.delegation_id IS NOT NULL AND (
          NEW.employee_id IS NULL OR NEW.runtime_id IS NULL OR NEW.job_id IS NULL
          OR NEW.pipeline_stage IS NULL OR NEW.source_invocation_id IS NULL
          OR NEW.model_invocation_id IS NULL
        ) THEN
          RAISE EXCEPTION 'token_usage.delegation_snapshot_required';
        END IF;
        RETURN NEW;
      END;
      $function$;

-- Triggers
CREATE TRIGGER app_metadata_schema_version_monotonic BEFORE INSERT OR UPDATE OF value ON app_metadata FOR EACH ROW EXECUTE FUNCTION guard_schema_version_monotonic();
CREATE TRIGGER trg_token_usage_billing_event AFTER INSERT OR UPDATE ON token_usage FOR EACH ROW EXECUTE FUNCTION append_token_usage_billing_event();
CREATE TRIGGER trg_validate_delegated_token_usage_snapshot BEFORE INSERT OR UPDATE ON token_usage FOR EACH ROW EXECUTE FUNCTION validate_delegated_token_usage_snapshot();
CREATE TRIGGER workflow_run_assign_history_sequence BEFORE INSERT ON workflow_run FOR EACH ROW EXECUTE FUNCTION assign_workflow_run_history_sequence();
CREATE TRIGGER trg_workspace_employee_sync_display_name AFTER UPDATE OF name ON workspace_employee FOR EACH ROW EXECUTE FUNCTION sync_employee_display_name();

-- CHECK constraints
ALTER TABLE "attachment" ADD CONSTRAINT "attachment_storage_provider_tos_check" CHECK ((storage_provider = 'tos'::text));
ALTER TABLE "auth_identity" ADD CONSTRAINT "auth_identity_provider_check" CHECK ((provider = 'sso'::text));
ALTER TABLE "employee_data_legal_hold" ADD CONSTRAINT "employee_data_legal_hold_resource_type_check" CHECK ((resource_type = ANY (ARRAY['employee_workspace'::text, 'artifact'::text, 'revision'::text, 'content_blob'::text])));
ALTER TABLE "openmontage_artifact_grant" ADD CONSTRAINT "openmontage_artifact_grant_operation_check" CHECK ((operation = ANY (ARRAY['READ'::text, 'WRITE'::text])));
ALTER TABLE "openmontage_artifact_grant" ADD CONSTRAINT "openmontage_artifact_grant_shape_check" CHECK ((((operation = 'READ'::text) AND (attachment_id IS NOT NULL) AND (artifact_role IS NULL) AND (file_name IS NULL) AND (media_type IS NULL) AND (size_bytes IS NULL) AND (sha256 IS NULL)) OR ((operation = 'WRITE'::text) AND (attachment_id IS NULL) AND (artifact_role IS NOT NULL) AND (file_name IS NOT NULL) AND (media_type IS NOT NULL) AND (size_bytes > 0) AND (sha256 IS NOT NULL))));
ALTER TABLE "openmontage_delegation_intent" ADD CONSTRAINT "openmontage_delegation_intent_status_check" CHECK ((status = ANY (ARRAY['creating'::text, 'provisioned'::text, 'drain_pending'::text, 'drained'::text, 'bound'::text])));
ALTER TABLE "openmontage_job_event" ADD CONSTRAINT "openmontage_job_event_application_status_check" CHECK ((application_status = ANY (ARRAY['pending'::text, 'applied'::text, 'ignored_terminal'::text])));
ALTER TABLE "openmontage_job_event" ADD CONSTRAINT "openmontage_job_event_schema_version_check" CHECK ((schema_version = 1));
ALTER TABLE "openmontage_job_event" ADD CONSTRAINT "openmontage_job_event_sequence_check" CHECK ((sequence > 0));
ALTER TABLE "openmontage_job_projection" ADD CONSTRAINT "openmontage_job_projection_last_applied_sequence_check" CHECK ((last_applied_sequence >= 0));
ALTER TABLE "openmontage_job_projection" ADD CONSTRAINT "openmontage_job_projection_sync_status_check" CHECK ((sync_status = ANY (ARRAY['CURRENT'::text, 'SYNCING'::text])));
ALTER TABLE "openmontage_notification_outbox" ADD CONSTRAINT "openmontage_notification_outbox_event_sequence_check" CHECK ((event_sequence > 0));
ALTER TABLE "openmontage_notification_outbox" ADD CONSTRAINT "openmontage_notification_outbox_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'delivered'::text, 'failed'::text])));
ALTER TABLE "workflow_definition" ADD CONSTRAINT "workflow_definition_status_check" CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'paused'::text, 'archived'::text])));
ALTER TABLE "workflow_trigger" ADD CONSTRAINT "workflow_trigger_misfire_policy_check" CHECK ((misfire_policy = ANY (ARRAY['skip'::text, 'fire_once'::text])));
ALTER TABLE "workflow_trigger" ADD CONSTRAINT "workflow_trigger_type_check" CHECK ((type = ANY (ARRAY['manual'::text, 'schedule'::text, 'event'::text])));

-- Expression indexes (COALESCE keys)
CREATE UNIQUE INDEX idx_agent_access_request_pending_unique ON public.agent_access_request USING btree (workspace_id, source_agent_name, requester_user_id, request_type, COALESCE(target_channel_name, ''::text)) WHERE (status = 'pending'::text);
CREATE UNIQUE INDEX idx_external_integration_provider_app_tenant ON public.external_integration USING btree (workspace_id, provider, app_id, COALESCE(tenant_key, ''::text)) WHERE (app_id IS NOT NULL);

-- NULLS-ordering indexes (Prisma cannot represent NULLS FIRST/LAST; Part B emitted the
-- index with default NULLS ordering, so drop and recreate it byte-faithful to v116).
DROP INDEX IF EXISTS "idx_workflow_node_run_approval_scan";
CREATE INDEX idx_workflow_node_run_approval_scan ON public.workflow_node_run USING btree (approval_scan_after NULLS FIRST, approval_deadline, id) WHERE ((status = 'waiting_approval'::text) AND (approval_id IS NOT NULL));

-- Redundant UNIQUE constraint (v116 has both a UNIQUE CONSTRAINT `workspace_slug_key`
-- and a standalone unique INDEX `idx_workspace_slug` on the same column — historical
-- hand-written redundancy. Prisma dedupes to the index and cannot round-trip the second
-- enforcement, so recreate the constraint to keep the baseline byte-faithful).
ALTER TABLE "workspace" ADD CONSTRAINT "workspace_slug_key" UNIQUE ("slug");
